sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var param = request.pathParams;
	var user = param.user;
	var output = {};
	var message = "";
	var allDependentsInfo = [];

	if(user){

		var grUser = new GlideRecord("sys_user");
		grUser.addEncodedQuery("user_name=" + user);
		grUser.setLimit(1);
		grUser.query();
		if(grUser.next()){
			var userID = grUser.getValue("sys_id");
		}
		if(userID){
			var grDependent = new GlideRecord("x_1806928_health_0_dependents_info");
			grDependent.addEncodedQuery("primary_insured=" + userID);
			grDependent.query();
			var count = grDependent.getRowCount();
			while(grDependent.next()){
				var name = grDependent.getValue("name");
				var relationship = grDependent.getDisplayValue("relationship");
				var age = grDependent.getDisplayValue("age");
				var obj = {
					"name" : name,
					"relationship" : relationship,
					"age" : age
				};
				allDependentsInfo.push(obj);
			}
		}
		else{
			gs.info("111RC user doesn't exist in ServiceNow");
			message = "user doesn't exist in serviceNow";
		}

	}
	else {
		gs.info("111RC user is empty");
		message = "user is empty";
	}
	output.message = message;
	output.allDependentsInfo = allDependentsInfo;

	if(!message){
		response.setBody(output);
		response.setStatus(200);
	}
	else
		response.setBody(output);
		response.setStatus(401);

})(request, response);
